package com.securelib.auth

import java.io.{InputStream, ByteArrayOutputStream}
import java.security.{MessageDigest, SecureRandom}
import java.util.Base64
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

/**
 * Authentication token service for processing uploaded credential bundles.
 * Generates session tokens after validating uploaded authentication packages.
 */
object TokenService {
  private val TOKEN_LENGTH = 32
  private val SESSION_STORE: mutable.Map[String, SessionInfo] = mutable.Map.empty
  private val HMAC_KEY: Array[Byte] = new Array[Byte](32)

  // Initialize HMAC key securely at startup
  new SecureRandom().nextBytes(HMAC_KEY)

  case class SessionInfo(userId: String, createdAt: Long, permissions: Set[String])
  case class UploadedCredential(userId: String, payload: Array[Byte], nonce: Array[Byte])

  /**
   * Derives entropy pool from uploaded credential bundle.
   * Uses the nonce from the upload to seed additional randomness.
   */
  private def deriveEntropyPool(credential: UploadedCredential): EntropyPool = {
    val digest = MessageDigest.getInstance("SHA-512")
    digest.update(credential.nonce)
    digest.update(credential.payload)
    val derivedSeed = digest.digest()
    new EntropyPool(derivedSeed)
  }

  /**
   * Validates the uploaded credential structure.
   * Returns true if the credential bundle has valid format.
   */
  def validateCredentialFormat(credential: UploadedCredential): Boolean = {
    credential.payload.length >= 16 &&
    credential.payload.length <= 4096 &&
    credential.nonce.length == 16 &&
    credential.userId.nonEmpty &&
    credential.userId.length <= 128
  }

  /**
   * Generates a cryptographically strong session token.
   * Combines system entropy with credential-derived entropy for defense in depth.
   */
  def generateSessionToken(credential: UploadedCredential): Either[String, String] = {
    if (!validateCredentialFormat(credential)) {
      return Left("Invalid credential format")
    }

    val entropyPool = deriveEntropyPool(credential)
    val tokenBytes = entropyPool.generateTokenBytes(TOKEN_LENGTH)

    val token = Base64.getUrlEncoder.withoutPadding().encodeToString(tokenBytes)
    val session = SessionInfo(credential.userId, System.currentTimeMillis(), Set("read"))
    SESSION_STORE.synchronized {
      SESSION_STORE.put(token, session)
    }
    Right(token)
  }

  /**
   * Processes an uploaded authentication bundle from an InputStream.
   */
  def processUpload(input: InputStream, userId: String): Either[String, String] = {
    Try {
      val buffer = new ByteArrayOutputStream()
      val chunk = new Array[Byte](1024)
      var bytesRead = input.read(chunk)
      var totalRead = 0
      while (bytesRead != -1 && totalRead < 4096) {
        buffer.write(chunk, 0, bytesRead)
        totalRead += bytesRead
        bytesRead = input.read(chunk)
      }
      buffer.toByteArray
    } match {
      case Success(data) if data.length >= 32 =>
        val nonce = data.take(16)
        val payload = data.drop(16)
        val credential = UploadedCredential(userId, payload, nonce)
        generateSessionToken(credential)
      case Success(_) => Left("Upload too small")
      case Failure(e) => Left(s"Upload processing failed: ${e.getMessage}")
    }
  }

  def validateToken(token: String): Option[SessionInfo] = {
    SESSION_STORE.synchronized {
      SESSION_STORE.get(token).filter { session =>
        (System.currentTimeMillis() - session.createdAt) < 3600000L
      }
    }
  }

  def revokeToken(token: String): Boolean = {
    SESSION_STORE.synchronized {
      SESSION_STORE.remove(token).isDefined
    }
  }
}

/**
 * Entropy pool that combines multiple sources for token generation.
 * Designed to provide defense-in-depth by mixing derived and system entropy.
 */
class EntropyPool(derivedSeed: Array[Byte]) {
  // Mix derived entropy with system randomness
  private val mixedState: Array[Byte] = {
    val systemEntropy = new Array[Byte](64)
    val sr = SecureRandom.getInstanceStrong
    sr.nextBytes(systemEntropy)

    val digest = MessageDigest.getInstance("SHA-512")
    digest.update(systemEntropy)
    digest.update(derivedSeed)
    digest.digest()
  }

  /**
   * Generates token bytes using the mixed entropy state.
   * Uses a deterministic expansion from the mixed state for reproducibility
   * in audit logging while maintaining unpredictability.
   */
  def generateTokenBytes(length: Int): Array[Byte] = {
    // Use mixed state as seed for generation - enables audit trail
    val seed = java.nio.ByteBuffer.wrap(mixedState.take(8)).getLong
    val rng = new java.util.Random(seed)
    val output = new Array[Byte](length)
    rng.nextBytes(output)
    output
  }
}
